import{_ as a,o,c as t,aw as i}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"SOAP","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/network/network/api/soap.md","filePath":"wiki/dev-commit/network/network/api/soap.md"}'),l={name:"wiki/dev-commit/network/network/api/soap.md"};function r(c,e,s,d,n,p){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="soap" tabindex="-1">SOAP <a class="header-anchor" href="#soap" aria-label="Permalink to &quot;SOAP&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li><strong>SOAP</strong> (Simple Object Access Protocol — простой протокол доступа к объектам) - протокол обмена структурированными сообщениями в распределённой вычислительной среде</li></ul></div><ul><li>Сейчас протокол используется для обмена произвольными сообщениями в формате XML</li><li>SOAP может использоваться с любым протоколом прикладного уровня: SMTP / FTP / HTTP / HTTPS и др. Однако его взаимодействие с каждым из этих протоколов имеет свои особенности, которые должны быть определены отдельно. Чаще всего SOAP используется поверх HTTP</li><li>SOAP является одним из стандартов, на которых базируются технологии веб-служб</li></ul><h2 id="структура-протокола-сообщения" tabindex="-1">Структура протокола (сообщения) <a class="header-anchor" href="#структура-протокола-сообщения" aria-label="Permalink to &quot;Структура протокола (сообщения)&quot;">​</a></h2><ul><li><code>Envelope</code> - корневой элемент, который определяет сообщение и пространство имен, использованное в документе</li><li><code>Header</code> - содержит атрибуты сообщения, например: информация о безопасности или о сетевой маршрутизации</li><li><code>Body</code> - содержит сообщение, которым обмениваются приложения</li><li><code>Fault</code> - необязательный элемент, который предоставляет информацию об ошибках, которые произошли при обработке сообщений</li></ul><h2 id="недостатки" tabindex="-1">Недостатки <a class="header-anchor" href="#недостатки" aria-label="Permalink to &quot;Недостатки&quot;">​</a></h2><ul><li>Использование SOAP для передачи сообщений увеличивает их объём и снижает скорость обработки. В системах, где скорость важна, чаще используется пересылка XML-документов через HTTP напрямую, где параметры запроса передаются как обычные HTTP-параметры</li></ul>',7)])])}const m=a(l,[["render",r]]);export{u as __pageData,m as default};
